const _ = require('lodash');
const moment = require('moment');
const TafStream = require('@taf/taf-stream');
const logger = require('./logger');
const constant = require('./constant');

module.exports = (DCache) => {

  return {
    /**
     * DCache删除字符串
     * @param key
     * @returns {boolean} 是否删除成功
     * @private
     */* delString(key) {
      try {
        const res = yield DCache.delString(key);
        if (res.iRet === 0) {
          return true;
        }
        logger.dcache.error('delString', key, JSON.stringify(res));
        return undefined;

      } catch (err) {
        /* istanbul ignore next */
        logger.dcache.error('delString', key, err);
        return undefined;
      }
    },

    /**
     * DCache获取字符串
     * @param key
     * @param forceMaster
     * @returns String
     * @private
     */* getString(key, forceMaster) {
      try {
        let res;
        if (forceMaster === constant.CONSTANT.FORCEMASTER) {
          const context = new TafStream.Map(TafStream.String, TafStream.String);
          context.insert('idcAreaSpecified', 'force-master');
          res = yield DCache.getString(key, { context });
        } else {
          res = yield DCache.getString(key);
        }
        if (res.iRet === 0) {
          return res.data.value;
        } else if (res.iRet === -6) {
          return null;
        }
        logger.dcache.error('getString', key, JSON.stringify(res));
        return undefined;

      } catch (err) {
        /* istanbul ignore next */
        logger.dcache.error('getString', key, err);
        return undefined;
      }
    },

    /**
     * DCache设置字符串
     * @param key
     * @returns {boolean} 是否插入成功
     * @private
     */* setString(key, value) {
      try {
        const res = yield DCache.setString(key, value);
        if (res.iRet === 0) {
          return true;
        }
        logger.dcache.error('setString', key, JSON.stringify(res));
        return undefined;

      } catch (err) {
        /* istanbul ignore next */
        logger.dcache.error('setString', key, err);
        return undefined;
      }
    },

    /**
     * DCache获取字符串及版本
     * @param key
     * @param forceMaster
     * @returns String
     * @returns {ver : ver , value : value}
     */* getStringWithVer(key, forceMaster) {
      try {
        let res;
        if (forceMaster === constant.CONSTANT.FORCEMASTER) {
          const context = new TafStream.Map(TafStream.String, TafStream.String);
          context.insert('idcAreaSpecified', 'force-master');
          res = yield DCache.getStringWithVer(key, { context });
        } else {
          res = yield DCache.getStringWithVer(key);
        }
        if (res.iRet === 0) {
          return res.data;
        } else if (res.iRet === -6) {
          return { value: null, ver: 1 };
        }
        logger.dcache.error('getStringWithVer', key, JSON.stringify(res));
        return undefined;
      } catch (err) {
        /* istanbul ignore next */
        logger.dcache.error('getStringWithVer', key, err);
        return undefined;
      }
    },

    /**
     * 根据版本号set数据
     * 如果报错返回false
     *
     * @param key
     * @param data
     * @param ver  版本号
     * @returns {boolean}
     */* setStringEx(key, data, ver, seconds, ignoreVer = false) {
      let res = {};
      try {
        res = yield DCache.setStringEx(key, data, ignoreVer ? undefined : ver ? ver : 1, true, seconds ? moment().unix() + seconds : 0);
        if (res.iRet === 0) {
          return true;
        } else if (res.iRet === -15) {
          return false;
        }
        logger.dcache.error('setStringEx ', key, data, ver, seconds, JSON.stringify(res));
        return undefined;

      } catch (err) {
        /* istanbul ignore next */
        if (err.iRet === -15) {
          return false;
        }
        logger.dcache.error('setStringEx', key, data, ver, seconds, err);
        return undefined;

      }
    },

    /**
     * 从DCache中批量获取数据
     * @param keys[]
     * @param isOrigin 是否是原始操作
     * @param forceMaster
     * @returns values[] (ret.length === keys.length)
     */* getBatch(keys, withVer = false, isOrigin = false, forceMaster) {
      const length = keys.length;
      keys = keys.filter(v => v);
      /* istanbul ignore if */
      if (!keys.length) {
        return _.fill(Array(length), null);
      }
      const vector = new TafStream.List(TafStream.String);
      keys.forEach(v => {
        vector.push(v);
      });
      try {
        let res;
        if (forceMaster === constant.CONSTANT.FORCEMASTER) {
          const context = new TafStream.Map(TafStream.String, TafStream.String);
          context.insert('idcAreaSpecified', 'force-master');
          res = yield DCache.getStringBatch(vector, { context });
        } else {
          res = yield DCache.getStringBatch(vector);
        }
        /* istanbul ignore if */
        if (res.iRet === -6) {
          return _.fill(Array(length), null);
        } else if (res.iRet !== 0) {
          return undefined;
        }
        const map = new Map();
        res.data.vtValue.value.forEach(v => {
          if (v.ret === 0) {
            if (!isOrigin) {
              const value = JSON.parse(v.value);
              map.set(v.keyItem, withVer ? { value: value.v, ver: v.ver } : value.v);
            } else {
              map.set(v.keyItem, withVer ? { value: v.value, ver: v.ver } : v.value);
            }
          }
        });
        return keys.map(v => {
          /* istanbul ignore if */
          if (v === null || v === undefined || !_.isString(v) || v === '') {
            return null;
          }
          const value = map.get(v);
          return value === undefined ? null : value;
        });
      } catch (err) {
        /* istanbul ignore next */
        logger.dcache.error('getBatch', keys, withVer, isOrigin, err);
        /* istanbul ignore next */
        return undefined;
      }
    },

    /**
     * 从DCache中批量获取数据
     * @param keys[]
     * @param
     * @param forceMaster
     * @returns {} (key : value)
     */* getBatch2Obj(keys, withVer = false, forceMaster) {
      const length = keys.length;
      keys = keys.filter(v => v);
      /* istanbul ignore if */
      if (!keys.length) {
        return _.fill(Array(length), null);
      }
      const vector = new TafStream.List(TafStream.String);
      keys.forEach(v => {
        vector.push(v);
      });
      try {
        let res;
        if (forceMaster === constant.CONSTANT.FORCEMASTER) {
          const context = new TafStream.Map(TafStream.String, TafStream.String);
          context.insert('idcAreaSpecified', 'force-master');
          res = yield DCache.getStringBatch(vector, { context });
        } else {
          res = yield DCache.getStringBatch(vector);
        }
        /* istanbul ignore if */
        if (res.iRet === -6) {
          return new Array(keys.length);
        } else if (res.iRet !== 0) {
          return undefined;
        }
        const map = new Map();
        res.data.vtValue.value.forEach(v => {
          if (v.ret === 0) {
            const value = JSON.parse(v.value);
            map.set(v.keyItem, withVer ? { value: value.v, ver: v.ver } : value.v);
          }
        });
        const obj = {};
        keys.forEach(v => {
          let value;
          /* istanbul ignore if */
          if (v === null || v === undefined || !_.isString(v) || v === '') {
            value = null;
          } else {
            value = map.get(v);
          }
          value === undefined ? null : value;
          obj[v] = value;
        });
        return obj;
      } catch (err) {
        /* istanbul ignore next */
        logger.dcache.error('getBatch2Obj', keys, withVer, err);
        /* istanbul ignore next */
        return undefined;
      }
    },

    * setBatchObj(obj) {
      const tafMap = new TafStream.Map(TafStream.String, TafStream.String);
      for (const key in obj) {
        tafMap.insert(key, obj[key]);
      }
      const res = yield DCache.setStringBatch(tafMap);
      if (res.iRet !== 0) {
        return undefined;
      }
      return true;
    },

    * getAllMainKey() {
      let keys = [];
      let index = 0;
      const count = 10000;
      while (true) {
        const context = new TafStream.Map(TafStream.String, TafStream.String);
        context.insert('idcAreaSpecified', 'force-master');
        const res = yield DCache.getAllMainKey(index, count, { context });
        if (res.iRet !== 0) {
          logger.dcache.error('getAllMainKey', res);
          return undefined;
        }
        keys = [ ...keys, ...res.data.mainKey.toObject() ];
        if (res.data.isEnd) {
          break;
        }
        index += count;
      }
      return keys;
    },

    // /**
    //  * 从DCache中批量插入数据
    //  * @param {Map} map
    //  * @returns {boolean}
    //  */
    // * setBatch(map) {
    //     if(_.isMap(map)) {
    //         if(!map.size) {
    //             return true;
    //         }
    //         let tafMap = new TafStream.Map(TafStream.String, TafStream.String);
    //         map.forEach(function(value, key) {
    //             tafMap.insert(key, value);
    //         });
    //         let res = yield DCache.setStringBatch(tafMap);
    //         return res.iRet === 0;
    //     } else {
    //         return false;
    //     }
    // },

    /**
     * 分布式锁(已废弃)
     * @param key 锁key
     * @param millisecond 加锁时间(毫秒) 不设默认为10s
     * @returns {boolean} 加锁成功/失败
     */* lock(key, millisecond) {
      millisecond = isNaN(millisecond) ? 10000 : parseInt(millisecond);
      const data = yield this.getStringWithVer(key, constant.CONSTANT.FORCEMASTER);
      console.log('--lock', data);
      const now = moment().valueOf();
      console.log(data.value, now, data.value > now);
      if (data && data.value && !isNaN(data.value)) {
        const lock_expire = data.value;
        if (lock_expire > now) {
          return false;
        }
      }
      let res = null;
      try {
        res = yield DCache.setStringEx(key, (now + millisecond).toString(), data ? data.ver : 1, true, 0);
      } catch (err) {
        return false;
      }
      return res.iRet === 0;
    },
  };
};
